using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;

namespace AkilliKisayol {
 public static class GesturePromptTests {
  internal static ShapeTemplate Shape(){return new ShapeTemplate{Points=Enumerable.Range(0,41).Select(i=>i<=20?new GesturePoint(0,i*10):new GesturePoint((i-20)*10,200)).ToList()};}
  static string Reply(string kind="copy",string combo="",string trigger=""){return LocalLlm.Json().Serialize(new{status="ready",name="Touchpad copy",trigger=trigger,app_id="global",message="",notes=new string[0],steps=new[]{new{kind=kind,combo=combo,text="",ms=0}}});}
  public static void Unit(Action<bool,string> check){
   var shape=Shape();var request=new LlmRequest{Prompt="Copy the selected text.",Gesture=shape,Applications=new List<string>()};var plan=LlmProtocol.ReadPlan(Reply(),request);check(plan.Ready&&plan.Binding.Key==0&&plan.Binding.Mods==0&&plan.Binding.Gesture.Points.Count==shape.Points.Count&&plan.Binding.Steps.Single().Key==67,"A touchpad prompt generates a valid executable action without requesting any keyboard activation");request.Prompt="Press Ctrl+S.";plan=LlmProtocol.ReadPlan(Reply("key","Ctrl+S","F8"),request);check(plan.Ready&&plan.Binding.Key==0&&plan.Binding.Steps.Single().Key==83&&plan.Binding.Steps.Single().Mods==2,"Keys requested as touchpad actions stay execution steps even if a model proposes a keyboard trigger");plan.Binding.Gesture.Points[0].X=999;check(shape.Points[0].X==0,"Prompt plans copy the recorded shape instead of mutating it");
   var payload=(Dictionary<string,object>)LlmProtocol.CreatePayload(request);var messages=(IEnumerable<object>)payload["messages"];var user=LocalLlm.Json().DeserializeObject((string)((Dictionary<string,object>)LocalLlm.Json().DeserializeObject(LocalLlm.Json().Serialize(messages.Last())))["content"]) as Dictionary<string,object>;check((string)user["trigger_type"]=="touchpad_shape"&&(string)user["trigger_hint"]==""&&(string)user["trigger_override"]=="","Both local and API payloads explicitly select touchpad activation without injecting a fake key");
   var keyboard=LlmProtocol.ReadPlan(Reply(),new LlmRequest{Prompt="Copy the selected text.",Applications=new List<string>()});check(!keyboard.Ready&&keyboard.Errors.Any(e=>e.Contains("trigger")),"Keyboard prompts still require an explicit activation key");
   var english=PromptParser.Parse("When I press F8, select all text and copy it.",new string[0]);check(english.Ready&&english.Binding.Key==119&&english.Binding.Steps.Count==2,"Rule fallback understands the English keyboard example shown by the application");english=PromptParser.Parse("Type \"Rock and roll, then go\", wait 0.5 seconds, then press Enter.",new string[0],shape:shape);check(english.Ready&&english.Binding.Gesture!=null&&english.Binding.Key==0&&english.Binding.Steps.Count==3&&english.Binding.Steps[0].Text=="Rock and roll, then go"&&english.Binding.Steps[1].Delay==500&&english.Binding.Steps[2].Key==13,"Touchpad rule fallback preserves quoted separators and interprets English text, waits and key actions without a trigger");check(PromptParser.Parse("0,5 saniye bekle",new string[0],shape:shape).Ready,"Decimal-comma legacy waits remain valid after parser optimization");
   english=PromptParser.Parse("When I press Del+5, copy the selected text.",new string[0]);check(english.Ready&&english.Binding.PrefixKey==46&&english.Binding.Key==53,"Rule fallback supports the same two-key activation used by the model planner");
   request.Gesture=new ShapeTemplate();bool refused=false;try{LlmProtocol.ReadPlan(Reply(),request);}catch(InvalidDataException){refused=true;}check(refused,"Invalid or missing shape samples cannot be saved as ready model plans");
   var candidate=new Binding{Name="Prepared L",Gesture=shape,Kind="Send key",SendKey=67,SendMods=2};var prepared=new PreparedShape(candidate);var regular=ShapeRecognition.Match(shape.Points,new[]{candidate},new GestureOptions());var fast=ShapeRecognition.MatchPrepared(shape.Points,new[]{prepared},new GestureOptions());check(regular.Binding==fast.Binding&&Math.Abs(regular.Score-fast.Score)<1e-10&&Math.Abs(regular.Margin-fast.Margin)<1e-10,"Prepared recognition retains the original match score and ambiguity margin");check(ShapeRecognition.Normalize(null).Count==0,"A missing preview trace is handled without crashing");
   var watch=Stopwatch.StartNew();for(int i=0;i<200;i++)ShapeRecognition.Match(shape.Points,new[]{candidate},new GestureOptions());long baseline=watch.ElapsedTicks;watch.Restart();for(int i=0;i<200;i++)ShapeRecognition.MatchPrepared(shape.Points,new[]{prepared},new GestureOptions());long optimized=watch.ElapsedTicks;File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"gesture-performance-test.json"),LocalLlm.Json().Serialize(new{iterations=200,baselineTicks=baseline,preparedTicks=optimized,frequency=Stopwatch.Frequency}));
   var many=Enumerable.Range(0,2000).Select(i=>new Binding{Id="key-"+i,Name="Key "+i,Key=32+i%200,Mods=i/200}).ToList();foreach(var item in many.Take(100).ToArray()){var copy=item.Copy();copy.Id="duplicate-"+item.Id;many.Add(copy);}watch.Restart();var overlaps=ShortcutConflicts.Find(many,new SystemShortcut[0],false);check(overlaps.Count==100&&overlaps.All(c=>c.Severity=="CONFLICT"),"Indexed conflict detection finds every deliberate overlap among 2,100 varied keyboard assignments");File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"conflict-performance-test.json"),LocalLlm.Json().Serialize(new{bindings=many.Count,expectedConflicts=100,actualConflicts=overlaps.Count,milliseconds=watch.ElapsedMilliseconds}));
  }
  static IEnumerable<Button> Buttons(DependencyObject parent){for(int i=0;i<VisualTreeHelper.GetChildrenCount(parent);i++){var child=VisualTreeHelper.GetChild(parent,i);if(child is Button)yield return (Button)child;foreach(var nested in Buttons(child))yield return nested;}}
  public static void Ui(MainWindow owner,Action<bool,string> check,Action<Window,string> screenshot){
   owner.ProductViewForTest("Touchpad gestures");check(Buttons(owner).Any(b=>Convert.ToString(b.Content)=="Create with prompt"),"Touchpad page exposes direct prompt-based shortcut creation");screenshot(owner,"touchpad-prompt-page.png");
   for(int mode=0;mode<2;mode++)using(var keyboard=new KeyboardEngine()){
    var state=new State();Binding old=mode==0?null:new Binding{Name="Existing shape",Kind="Send key",SendKey=67,SendMods=2,Gesture=Shape()};if(old!=null)state.Bindings.Add(old);using(var gestures=new GestureEngine(keyboard,()=>state,()=>Profiles.Effective(state),false)){
     Exception failure=null;var dialog=new GestureWindow(gestures,keyboard,state,()=>new SystemShortcut[0],old,(sample,prior)=>{var prompt=new PromptWindow(keyboard,new Binding[0],new string[0],previous:prior,profiles:state.Profiles,activeProfile:state.ActiveProfileId,gesture:sample);prompt.Planner=(request,progress,cancellation)=>{check(request.Gesture!=null&&string.IsNullOrEmpty(request.Trigger),"Nested touchpad prompt supplies its real recorded shape and no keyboard override");return Task.FromResult(LlmProtocol.ReadPlan(Reply(),request));};Application.Current.Dispatcher.BeginInvoke(new Action(async()=>{try{await prompt.StartModelForTest("Copy the selected text.");check(prompt.PlanForTest().Ready&&prompt.CanSaveForTest()&&prompt.TriggerForTest()=="","Touchpad preview is saveable without filling a hidden or synthetic trigger");if(mode==0)screenshot(prompt,"touchpad-prompt-preview.png");prompt.SaveForTest();}catch(Exception error){failure=error;prompt.Close();}}));return prompt;},true){Owner=owner};dialog.Show();try{if(mode==0)check(!dialog.CanPromptForTest,"Prompt action waits for an actual recorded shape");dialog.RecordForTest(Shape().Points);check(dialog.CanPromptForTest,"Recording a shape enables prompt action creation");check(dialog.TraceFitsForTest,"Recorded shape preview fits inside the drawing area without clipping");dialog.PromptForTest();if(failure!=null)throw failure;var draft=dialog.DraftForTest();check(draft.Kind=="Workflow"&&draft.Key==0&&draft.Gesture!=null&&draft.Prompt=="Copy the selected text."&&draft.Steps.Single().Key==67,"Accepted prompt plan is attached to the recorded shape");if(old!=null)check(draft.Id==old.Id&&Rules.Validate(draft,state.Bindings)==null,"Editing an existing non-prompt shape through a prompt preserves its identity without self-conflicts");else screenshot(dialog,"touchpad-prompt-action-preview.png");dialog.Hide();Application.Current.Dispatcher.BeginInvoke(new Action(()=>dialog.SaveForTest()));check(dialog.ShowDialog()==true&&dialog.Result.Gesture!=null,"The final shape shortcut saves through the actual Save button after action preview");}finally{dialog.Close();}check(!keyboard.Paused,"Closing the nested touchpad prompt restores the keyboard pause state");
    }
   }
   owner.ProductViewForTest("Home");
  }
  public static int Real(){
   string report=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"gesture-model-test.json");var results=new List<object>();
   using(var model=new LocalLlm())try{
    var state=Storage.Read(Storage.FilePath);
    string browser=state.ApplicationPaths.FirstOrDefault(p=>File.Exists(p)&&Path.GetFileName(p).Equals("brave.exe",StringComparison.OrdinalIgnoreCase))??state.ApplicationPaths.FirstOrDefault(p=>File.Exists(p)&&BrowserSupport.IsBrowser(p));
    string[] prompts={"Select all text and copy it.","Type \"Touchpad ready\", wait 250 ms, then press Enter.","Press Ctrl+S.","Open https://www.youtube.com/ in the selected browser."};
    for(int i=0;i<prompts.Length;i++){
     var watch=Stopwatch.StartNew();var request=new LlmRequest{Prompt=prompts[i],Applications=i==3?new List<string>{browser}:new List<string>(),TargetApp=i==3?browser:"",ModelPath=state.ModelPath,Gesture=Shape()};
     // Generate and inspect a plan only; never launch the browser or execute its actions.
     var plan=model.AnalyzeAsync(request,p=>{},CancellationToken.None).GetAwaiter().GetResult();
     bool valid=plan.Ready&&plan.Binding.Gesture!=null&&plan.Binding.Key==0&&(i==0?plan.Binding.Steps.Count==2&&plan.Binding.Steps[0].Key==65&&plan.Binding.Steps[1].Key==67:i==1?plan.Binding.Steps.Count==3&&plan.Binding.Steps[0].Text=="Touchpad ready"&&plan.Binding.Steps[1].Delay==250&&plan.Binding.Steps[2].Key==13:i==2?plan.Binding.Steps.Count==1&&plan.Binding.Steps[0].Key==83&&plan.Binding.Steps[0].Mods==2:plan.Binding.AppPath==""&&(plan.Binding.Kind=="Browser website"?Rules.SameApp(plan.Binding.BrowserPath,browser)&&plan.Binding.Target=="https://www.youtube.com/":plan.Binding.Steps.Any(s=>s.Kind=="Open content"&&Rules.SameApp(s.AppPath,browser)&&s.Text=="https://www.youtube.com/")));
     results.Add(new{prompt=prompts[i],passed=valid,milliseconds=watch.ElapsedMilliseconds,binding=plan.Binding,errors=plan.Errors});if(!valid)throw new Exception("Touchpad model scenario failed: "+i);
    }
    File.WriteAllText(report,LocalLlm.Json().Serialize(new{status="PASS",results=results}));return 0;
   }catch(Exception error){File.WriteAllText(report,LocalLlm.Json().Serialize(new{status="FAIL",error=error.ToString(),results=results,response=model.LastResponse,diagnostics=model.LastDiagnostics}));return 1;}
  }
 }
}
